/* HEXA BATTLEGROUNDS upgrade — PART 18 OF 31. Only for databases that already ran setup part-01…; Run in order. Safe to re-run. */ create or replace function captain_reveal(p_token text, p_instance uuid, p_part int) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; mi mission_instances; mt mission_templates; v_part jsonb; v_cost int; v_ans text; begin p := _auth_captain(p_token); select * into mi from mission_instances where id = p_instance for update; if mi.id is null or mi.team_id <> p.team_id or mi.status <> 'active' then raise exception 'NOT_FOUND'; end if; v_cost := _reveal_cost(mi); if v_cost = 0 then raise exception 'NO_REVEAL_HERE'; end if; select * into mt from mission_templates where id = mi.template_id; v_part := mt.parts -> p_part; if v_part is null or (v_part -> 'accept') ? '{KEY}' then raise exception 'NO_REVEAL_HERE'; end if; v_ans := v_part -> 'accept' ->> 0; if mi.revealed ? p_part::text then return jsonb_build_object('part', p_part, 'answer', v_ans, 'cost', 0); end if; perform _apply(mi.team_id, 'reveal', -v_cost, 0, 0, 0, mi.id::text || ':' || p_part, 'Revealed an answer'); update mission_instances set revealed = revealed || jsonb_build_object(p_part::text, v_ans) where id = mi.id; perform _ping_team(mi.team_id, 'hint'); return jsonb_build_object('part', p_part, 'answer', v_ans, 'cost', v_cost); end $$;
